console.log('Total raw BIST stocks cataloged:', bistRaw.length);

const output = `export interface BISTStockMetadata {
  code: string;
  name: string;
  sector: string;
  basePrice: number;
  peRatio: number;
  pbRatio: number;
  roe: number;
  netMargin: number;
  debtToEquity: number;
  baseScore: number;
  riskScore: number;
}

export const BIST_ALL_STOCKS: BISTStockMetadata[] = ${JSON.stringify(
  bistRaw.map(x => ({
    code: x.c,
    name: x.n,
    sector: x.s,
    basePrice: x.p,
    peRatio: x.pe,
    pbRatio: x.pb,
    roe: x.roe,
    netMargin: x.nm,
    debtToEquity: x.de,
    baseScore: x.sc,
    riskScore: x.rk,
  })),
  null,
  2
)};

// Lookup or dynamic generator for any unlisted or newly listed BIST stock
export function findOrGenerateBistStock(code: string): BISTStockMetadata {
  const upper = code.toUpperCase().replace('.IS', '').trim();
  const existing = BIST_ALL_STOCKS.find(s => s.code === upper);
  if (existing) return existing;

  // Dynamic fallback for any newly listed BIST stock
  return {
    code: upper,
    name: \`\${upper} BIST Ortaklığı\`,
    sector: 'Diğer / Çeşitli Sanayi',
    basePrice: 50.0,
    peRatio: 10.5,
    pbRatio: 2.1,
    roe: 25.0,
    netMargin: 12.0,
    debtToEquity: 0.5,
    baseScore: 70,
    riskScore: 48,
  };
}
`;

fs.writeFileSync(path.join(__dirname, '../src/services/bistDirectory.ts'), output);
console.log('Successfully wrote src/services/bistDirectory.ts with', bistRaw.length, 'stocks.');
